          "paragraphs": [
            "将保存视为多个相关记录：路线和世界、篝火和附近的行李、每个玩家的库存和状况以及基于运行的进度（例如食物需求）。当这些记录中只有一项不同时，返回的玩家可以报告“我的保存已消失”。在尝试另一台主机或另一次重新连接之前，记下更改的记录。",
            "Patch 2.6.a 表示 Citadel 篝火保存应该正确跟踪篝火周围的行李和其他物体。它还表示非主机游戏保存变得更加一致，但原始主机以外的玩家无法获得完整的世界状态，并且如果他们从保存中托管，可能会看到物品生成的奇怪现象。该警告属于答案，而不是脚注。"
          ],
