      "intro": "Si el modo multijugador de PEAK falla, primero escriba el síntoma exacto y el parche mostrado por el cliente. Los parches 2.5.a, 2.6.a y 2.6.b corrigen muchos casos conocidos de reconexión, guardado, código de sala y unión tardía, pero las notas oficiales dejan advertencias para guardados que no son del host y conexiones lentas o regionales. Utilice la siguiente matriz de problemas y luego vuelva a realizar la prueba en una ejecución controlada.",
      "answer": "La mayoría de los informes de conexión de PEAK se dividen en una de tres rutas: la ruta de unión al lobby, la ruta del mundo guardado o la ruta de conexión en vivo. Los errores de código de sala y los bloqueos de Loading comienzan con el flujo de unión; muerte, esqueletos y elementos faltantes después de que Continue Run comience con el jugador guardado o el estado mundial; Las indicaciones de voz y del controlador necesitan comprobaciones de entrada locales. Los pasos a continuación separan las correcciones oficiales de las posibilidades informadas por los jugadores para que un reintento no se convierta en una suposición.",
