                "zxterm0zx",
                "Dispara a través del cañón MESA con un cañón explorador y aterriza dentro de la zona objetivo.",
                "Discapacitado; Utilice una expedición normal.",
                "Patch 2.4.c dice que el requisito de desbloqueo ahora debería funcionar correctamente. La publicación oficial no documenta una regla de migración segura para un intento fallido.",
                "Utilice una carrera normal nueva, coloque el cañón con cuidado, aterrice en la zona objetivo y anote la versión si el aterrizaje es visiblemente correcto pero no aparece ningún desbloqueo.",
                "Requisito fijado en 2.4.c; Informe del jugador pendiente por nuevas fallas."
