      "intro": "PEAK マルチプレイヤーが失敗する場合は、まず正確な症状とクライアントによって示されたパッチを書き留めます。パッチ 2.5.a、2.6.a、および 2.6.b では、多くの既知の再接続、保存、ルームコード、および遅延参加のケースが修正されていますが、公式ノートには、非ホスト保存および低速接続または地域接続に関する警告が残されています。以下の問題マトリックスを使用して、制御された実行で再テストしてください。",
