      "intro": "Gloom는 Patch 2.0.a의 Final Ascent와 함께 도착했으며 나중에 Citadel와 함께 임시 순환으로 나타났습니다. 이에 접근하는 가장 안전한 방법은 현재 경로를 확인하고, 가시성 및 이동 결정을 통해 팀을 하나로 유지하고, 배지 및 부활 동작을 버전에 따라 처리하는 것입니다. Patch 2.6.b는 명명된 Gloom 또는 Citadel Medieval History 부활 사례를 수정합니다.",
