            "In den „Was zählt“-Notizen gehen viele Fehlversuche schief. Einige Abzeichen werden sofort gewährt, während andere ein Lagerfeuer oder eine lebendige Flucht erfordern. Das Füttern eines anderen Spielers kann dem Feeder Essensabzeichen gutschreiben lassen; Es wird dem Spieler, der den Gegenstand erhält, nicht automatisch eine Gutschrift gutgeschrieben."
