                "Verwenden Sie erneut die normale Scroll-Route. Wenn Sie es bereits vor dem Fehler verdient haben, blättern Sie zur zweiten Seite des Leitfadens und verwenden Sie das Salut-Emote als offiziellen vorübergehenden Zuschuss.",
