                "Medieval History",
                "Passiere DIE ZITADELLE, ohne von Fallen getroffen zu werden. Petrified Rocks zählen nicht als Fallentreffer; Pfeilfallenaktivierung mit einem Gegenstand und Drowsy von Gepäckfallen zählen.",
                "Behinderte; Verwenden Sie eine normale Expedition.",
