            "Verwenden Sie den temporären Cheat 2.4.c Bookworm nicht als allgemeinen Fix. Im offiziellen Beitrag heißt es, dass es sich um Spieler handelt, die das Abzeichen bereits erhalten haben, und es wird darauf hingewiesen, dass es für alle funktioniert. Dies ist eine Ausnahme, um verlorene Fortschritte zu reparieren, und keine Möglichkeit, die Journalanforderung zu überspringen. Für andere Abzeichen verwenden Sie eine neue normale Auflage und den offiziellen Ausgabekanal, sofern noch eine aktuelle Reproduktion vorhanden ist."
