            "Wie funktionieren PEAK-Lagerfeuerrettungen?",
            "Das Lagerfeuer zeichnet einen Laufzustand auf, der den Weltkontext und Objekte in der Nähe umfasst. Patch 2.6.a verbessert die Citadel-Gepäckverfolgung, aber der offizielle Hinweis besagt, dass bei Nicht-Host-Speicherungen immer noch der vollständige Weltstatus weggelassen werden kann."
