            "Wenn ein Spieler wiederbelebt wird oder sich wieder verbindet, notieren Sie, ob der Lauf neu war, von einem Lagerfeuer geladen wurde oder mitten im Spiel beigetreten ist. Patch 2.6.b sollte den benannten Medieval History-Fall korrigieren, aber ein fehlendes Badge benötigt immer noch den genauen Trap-, Revive-, Host- und Versionskontext. Verwenden Sie die Seite zur Fehlerbehebung bei Erfolgen für die Auslösertabelle."
