            "Der sicherste erneute Test behält den ursprünglichen Host bei, verwendet eine normale Expedition und zeichnet auf, ob der Spieler am Leben, tot oder wiederbelebt war, als Citadel erreicht wurde. Wenn ein Nicht-Host von einem Speicherstand aus hostet, heißt es in der Anmerkung zu 2.6.a, dass das Spawnen von Gegenständen immer noch etwas seltsam sein kann. Das beweist nicht, dass das Abzeichen aus demselben Grund versagt hat, aber es ist ein wesentlicher Zusammenhang."
