            "Un lobby fonctionnel ne prouve pas que le chemin audio local ou le focus du contrôleur fonctionnent. Patch 2.04.a a ajouté un indicateur HUD pour les états push-to-talk ou push-to-mute en sourdine. Utilisez cet état visible, le périphérique d’entrée du système d’exploitation et un court test de lobby pour séparer un paramètre local d’un rapport réseau. Ne désactivez pas tous les contrôles de sécurité ou de confidentialité en tant que correctif générique.",
