            "Les notes « ce qui compte » sont celles où de nombreuses tentatives infructueuses tournent mal. Certains badges sont accordés immédiatement, tandis que d'autres nécessitent la fin d'un feu de camp ou une évasion vivante. Nourrir un autre joueur peut créditer le chargeur pour des badges liés à la nourriture ; il ne crédite pas automatiquement le joueur qui reçoit l'objet."
