            "Considérez une sauvegarde comme plusieurs enregistrements liés : l'itinéraire et le monde, le feu de camp et les bagages à proximité, l'inventaire et l'état de chaque joueur, ainsi que la progression basée sur la course, comme les besoins alimentaires. Un joueur qui revient peut signaler « ma sauvegarde a disparu » lorsqu'un seul de ces enregistrements est différent. Notez quel enregistrement a changé avant d'essayer un autre hôte ou une autre reconnexion.",
            "Patch 2.6.a indique que les sauvegardes de feu de camp Citadel devraient suivre correctement les bagages et autres objets autour du feu de camp. Il indique également que les sauvegardes de jeu non hôtes sont devenues plus cohérentes, mais que les joueurs autres que l'hôte d'origine n'obtiennent pas l'état complet du monde et peuvent voir des objets bizarres apparaître s'ils hébergent à partir d'une sauvegarde. Cette mise en garde appartient à la réponse, pas à une note de bas de page."
