          "paragraphs": [
            "Patch 2.5.a indique que les joueurs se connectant à un jeu dans une autre partie du monde ne devraient plus rester bloqués sur Loading. Il s’agit d’une solution pour un cas précis, et non d’une promesse qu’une connexion longue distance aura la même latence qu’une connexion locale. Si le même groupe travaille dans une région et tombe en panne dans une autre, enregistrez la paire de régions et l'heure plutôt que de parler d'une panne globale.",
            "Les réalisations basées sur l'exécution nécessitent une vérification supplémentaire. La référence du badge indique que les Custom Run désactivent les badges, et Patch 2.6.a indique que la progression de l'hôte est désormais enregistrée sur un feu de camp. Une reconnexion peut toujours exposer un état ancien ou différent si le joueur rejoint une sauvegarde non hôte. Pour une nouvelle tentative de badge, utilisez une exécution normale, conservez l'hôte d'origine et enregistrez si le joueur a été réanimé ou vivant au moment du déclenchement."
          ],
