            "La mise à jour Final Ascent a introduit Citadel aux côtés de Gloom et d'autres systèmes de route tardive. Patch 2.01.a a ensuite amélioré la génération de niveaux Citadel pour éviter les obstacles flottants, et Patch 2.03.a a placé un nouveau lot de cartes Gloom/Citadel dans la rotation quotidienne pendant la préparation des Caldera et The Kiln. Patch 2.04.a a ramené Caldera et The Kiln, donc Citadel doit être lu comme faisant partie d'un pool changeant plutôt que comme un point de terminaison quotidien permanent.",
            "Les messages officiels constituent une preuve solide de la publication et des correctifs, mais ils ne fournissent pas de carte complète des pièges ni d'ordre d'itinéraire garanti. Utilisez la page d'image et de carte comme contexte, puis lisez l'état du piège que présente réellement la session en cours. Cela permet de conserver une tentative Medieval History reproductible au lieu d'être basée sur une ancienne capture d'écran."
