          "title": "Citadel enregistre, se reconnecte et relance",
          "paragraphs": [
            "Une défaillance du badge Citadel peut être une défaillance de condition ou une défaillance d’état. Patch 2.5.a a corrigé un cas où le chargement d'une sauvegarde de feu de camp Citadel empêchait Medieval History. Patch 2.6.a a amélioré le suivi des feux de camp pour les bagages et les objets à proximité et a corrigé la progression basée sur l'exécution de l'hôte lors d'un feu de camp. Patch 2.6.b a corrigé un cas où la réactivation dans Gloom ou Citadel pouvait empêcher Medieval History. Gardez ces chemins séparés lorsque vous signalez un résultat.",
            "Le nouveau test le plus sûr conserve l'hôte d'origine, utilise une expédition normale et enregistre si le joueur était vivant, mort ou réanimé lorsque le Citadel a été atteint. Si un non-hôte héberge une sauvegarde, la note 2.6.a indique que l'apparition d'éléments peut encore être un peu bizarre. Cela ne prouve pas que le badge a échoué pour la même raison, mais c'est un contexte essentiel."
          ],
