            "Le matériel officiel vérifié n’indique pas que PEAK dispose d’un navigateur de lobby public, d’une file d’attente de mise en relation automatique ou d’une liste de serveurs pour les étrangers. Cette absence est une limite source et non une preuve qu’aucune fonctionnalité future ne peut exister. Vérifiez une nouvelle annonce officielle avant de modifier cette réponse et conservez les demandes actuelles des joueurs comme commentaires."
