            "Comece com o menor teste reversível. Verifique a construção atual, use uma sala nova, pergunte se o anfitrião ou o jogador que está entrando viu o problema e altere uma variável. Nunca publique um código de sala, identificador de conta, senha ou token em um relatório de suporte."
