            "As notas “o que conta” são onde muitas tentativas fracassadas dão errado. Alguns emblemas são concedidos imediatamente, enquanto outros exigem o fim da fogueira ou uma fuga viva. Alimentar outro jogador pode creditar ao alimentador emblemas relacionados à comida; não credita automaticamente o jogador que recebe o item."
