            "Patch 2.6.a diz que os salvadores de fogueira Citadel devem rastrear adequadamente a bagagem e outros objetos ao redor da fogueira. Ele também diz que os salvamentos de jogos não-hosts se tornaram mais consistentes, mas que outros jogadores que não o host original não obtêm o estado mundial completo e podem ver uma estranheza na geração de itens se hospedarem a partir de um salvamento. Essa advertência pertence à resposta, não a uma nota de rodapé."
