            "Se o controlador não puder selecionar Continue Run, teste o foco do menu e a entrada do teclado sem alterar o salvamento. Esse relatório de contributos é diferente de um relatório sobre o estado mundial. Mantenha os dois problemas separados para que uma correção posterior possa resolver o caminho correto. A página de solução de problemas multijogador inclui o controlador e verificações de voz."
