            "O material oficial verificado não afirma que PEAK tenha um navegador de lobby público, uma fila de matchmaking automática ou uma lista de servidores para estranhos. Essa ausência é um limite de origem, e não uma prova de que nenhuma característica futura possa existir. Verifique um novo anúncio oficial antes de alterar esta resposta e mantenha as solicitações atuais dos jogadores rotuladas como feedback."
