            "Inizia con il test reversibile più piccolo. Verifica la build corrente, utilizza una nuova stanza, chiedi se l'host o il giocatore che si unisce ha visto il problema e modifica una variabile. Non pubblicare mai il codice della camera, l'identificatore dell'account, la password o il token in un rapporto di supporto."
