            "Evita di considerare Gloom come un motivo per affrettarti. Una breve deviazione che preservi una via di ritirata può essere più sicura di un impegno diretto che consuma l’ultimo elemento di recupero. Registra la data, la patch, l'etichetta del percorso e la prima decisione importante; quella nota rimarrà utile anche quando il pool giornaliero cambierà."
