            "I post ufficiali sono una prova evidente del rilascio e delle correzioni, ma non forniscono una mappa completa delle trappole o un ordine di percorso garantito. Utilizza l'immagine e la pagina della mappa come contesto, quindi leggi lo stato trap effettivamente presentato dalla sessione corrente. Ciò mantiene riproducibile un tentativo Medieval History anziché basato su un vecchio screenshot."
