            "Quando ti unisci a estranei, mantieni la prima corsa breve e concorda il percorso, esprimi le aspettative e se il gruppo sta testando un badge o sta semplicemente scalando. Non condividere pubblicamente le credenziali dell'account o i codici delle stanze private. Se un canale della community dichiara di essere ufficiale, verificalo tramite un collegamento sviluppatore prima di fidarti di esso."
